general.customPopupCss:
/* --------------------------------- */
/* ----- YOMITAN POPUP STYLING ----- */
/* ---- Last Updated 2025-07-26 ---- */
/* --------------------------------- */

/* --------------- GENERAL --------------- */

body {
    font-family: "Noto Sans JP", "游教科書体", "UD デジタル 教科書体 NP", "UDDigiKyokashoN-R", "Hiragino Mincho ProN", "ヒラギノ明朝 ProN", "Noto Serif JP", system-ui;
    font-size: clamp(0.7rem, 3vw, 0.9rem);
}

/* --- Term --- */
.headword {
    font-family: "UD デジタル 教科書体 NP", "UDDigiKyokashoN-R", "Noto Serif JP", system-ui;
    font-size: 110%;
}

/* --- Furigana --- */
.headword-reading  {
    font-family: "UD デジタル 教科書体 NP", "UDDigiKyokashoN-R", "Hiragino Mincho ProN", "ヒラギノ明朝 ProN", system-ui;
    font-size: 110%;
}

.headword ruby rt {
    margin-top: 8px;
    margin-bottom: 6.5px;
    color: aquamarine;
}

.headword-list-tag-list .tag {
    font-family: "UD デジタル 教科書体 NP", "UDDigiKyokashoN-R", "Hiragino Mincho ProN", "ヒラギノ明朝 ProN", system-ui;
}

.headword-list-tag-list .tag {
    margin: 2.5px;
    margin-top: 6px;
}

.headword-list-tag-list .tag:first-child {
    margin-left: 1em;
}

.headword-list-tag-list .tag .tag-label {
    --tag-color: #4B6F56;
}

.headword-list-tag-list {
    margin-left: -2.5px;
}

.entry-body-section {
    margin: 4px 0;
}

.frequency-item {
    font-family: 'noka-mono', 'Courier New', monospace; 
}

/* --------------- DICTIONARY SPECIFIC --------------- */

:root[data-theme="dark"] {
    --atamadaka-color: #F5436D;
    --heiban-color: #39C1FF;
    --nakadaka-color: #fca311;
    --odaka-color: #40D4A6;
    /* --background-color: #212228; */
    /* --background-color: #282828; */
    --background-color: #26282c;
    --tag-dictionary-background-color: #294be3;

    .definition-item[data-dictionary='大辞泉 第二版'] {
        --daijisen-black: #FFFFFF;
        --daijisen-white: #cdcdcd;
        --daijisen-blue: #00AAFF;
        --daijisen-header-djs: #A0484F;
        --daijisen-header-djsp: #7A7A7A;
        --daijisen-header-text: #000000;
        --daijisen-logo-color: #DDDDDD;
        --daijisen-background-l3: #C0C0C0;
        --daijisen-accent-mark: #FF6666;
        --daijisen-accent-slash: #A0A0A0;
    }

    .definition-item[data-dictionary='明鏡国語辞典 第三版'] {
        --meikyo-white: #cdcdcd;
        --meikyo-black: #CCCCCC;
        --meikyo-red: #FF3333;
        --meikyo-gray: #BBBBBB;
        --meikyo-pink: #CC6666;
        --meikyo-dark-red: #993333;
        --meikyo-fbox-white: #FFFFFF;
        --meikyo-fbox-gray: #CCCCCC;
        --meikyo-box-gray: #663333;

        .gloss-sc-span[data-sc-class="gaiji"] .gloss-image {
            -webkit-filter: invert(90%);
            filter: invert(90%);
        }
    }
}

/* --------------- FREQUENCY DICT COLORS --------------- */

