/* --------------- PITCH --------------- */

.pronunciation-group-list {
    padding-left: 0.7em !important;
}

li.pronunciation-group {
    list-style-type: none;
}

.pronunciation-text-container {
    font-family: "Noto Sans JP", system-ui;
    font-size: 110%;
}

.pronunciation-downstep-notation {
    margin-left: 0.2em;
    /* color: #7190be; */
    color: #37e3b2cc;
    /* font-weight: bold; */
}

.pronunciation:nth-child(n+2) {
    margin-left: 0.2em;
}


/* --------------- KANJI DICTS --------------- */

/* remove misc dict classifications/codepoints/stats */
.kanji-glyph-data>tbody>tr:nth-child(n + 3) {
    display: none;
}

/* remove stroke diagram, freq, header for next entries */
div.entry[data-type='kanji']:nth-child(n + 2) .kanji-glyph-container,
div.entry[data-type='kanji']:nth-child(n + 2) [data-section-type='frequencies'],
div.entry[data-type='kanji']:nth-child(n + 2) table.kanji-glyph-data>tbody>tr:first-child {
    display: none;
}

/* remove 'No data found' */
.kanji-info-table-item-value-empty {
    display: none;
}

/* reduce extra padding */
.kanji-glyph-data,
div.entry[data-type='kanji'],
div.entry[data-type='kanji']:nth-child(n + 2) .kanji-glyph-data>tbody>tr>*,
.kanji-glyph-data dl.kanji-readings-japanese,
div.entry[data-type='kanji']:nth-child(n + 2) .kanji-glyph-data dl.kanji-readings-chinese[data-count='0'] {
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    margin-bottom: 0em;
    margin-top: 0 !important;
}

/* remove horizontal lines */
.entry+.entry[data-type='kanji'],
div#dictionary-entries>div.entry:nth-child(n + 2) .kanji-glyph-data>tbody>tr>* {
    border-top: none !important;
}

/* change decimal list */
.kanji-gloss-list {
    list-style-type: circle;
}   

/* --------------- OPTIONAL AUXILARY OPTIONS --------------- */

/* Only shows the first 7 frequency lists */
span.frequency-group-item:nth-child(n+8) {
    display: none;
}

/* Hides the add reading button */
button[title^="Add reading"] 
{
    display:none;
}

/* --------------- COLOURED PITCH ACCENT V1.3  --------------- */
/* ------------------ Credit to koiyakiya -------------------- */
/* Do note this will highlight the word according to the first entry in the first pitch dictionary that you have displayed. 
There is no better way to do this without modifying Yomitan's internal code (Javascript). */

/* Atamadaka highlighting for headword */
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="1"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="1"]) .headword-term {
    color: var(--atamadaka-color);
    --headword-current-kanji-border-color: var(--atamadaka-color);
}
/* Atamadaka highlighting for border top on pronunciation list */
.pronunciation[data-pitch-accent-downstep-position="1"] {
    --pronunciation-annotation-color: var(--atamadaka-color);
}
/* ---Heiban--- */
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="0"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="0"]) .headword-term {
    color: var(--heiban-color);
    --headword-current-kanji-border-color: var(--heiban-color);
}
.pronunciation[data-pitch-accent-downstep-position="0"] {
    --pronunciation-annotation-color: var(--heiban-color);
}
/* ---End Heiban--- */

/* ---Kifuku Section--- */

/* Everything will be initially colored as nakadaka if in the kifuku category */
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="2"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="2"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="3"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="3"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="4"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="4"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="5"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="5"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="6"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="6"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="7"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="7"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="8"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="8"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="9"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="9"]) .headword-term,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="10"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child[data-pitch-accent-downstep-position="10"]) .headword-term {
	color: var(--nakadaka-color);
    --headword-current-kanji-border-color: var(--nakadaka-color);
}

.pronunciation[data-pitch-accent-downstep-position="2"],
.pronunciation[data-pitch-accent-downstep-position="3"],
.pronunciation[data-pitch-accent-downstep-position="4"],
.pronunciation[data-pitch-accent-downstep-position="5"],
.pronunciation[data-pitch-accent-downstep-position="6"],
.pronunciation[data-pitch-accent-downstep-position="7"],
.pronunciation[data-pitch-accent-downstep-position="8"],
.pronunciation[data-pitch-accent-downstep-position="9"],
.pronunciation[data-pitch-accent-downstep-position="10"] {
    --pronunciation-annotation-color: var(--nakadaka-color);
}

/* ---End nakadaka--- */

/* Now, we check manually if the first entry in the first pitch accent dict
   is odaka 尾高 */
.entry:has(.pronunciation-list li:first-child .pronunciation-mora:last-child[data-pitch="high"][data-pitch-next="low"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child .pronunciation-mora:last-child[data-pitch="high"][data-pitch-next="low"]) .headword-term {
    color: var(--odaka-color) !important;
    --headword-current-kanji-border-color: var(--odaka-color) !important;
}
.pronunciation:has(.pronunciation-mora:last-child[data-pitch="high"][data-pitch-next="low"]) {
    --pronunciation-annotation-color: var(--odaka-color) !important;
}

/* ---End kifuku--- */

/* Check if word only has one mora. If that single mora is high while the next 
   (nonexistent) mora is low, that means it's atamadaka, and thus we set it as such.*/
.entry:has(.pronunciation-list li:first-child .pronunciation-mora:last-child[data-position="0"][data-pitch="high"][data-pitch-next="low"]) .headword-term *,
.entry:has(.pronunciation-list li:first-child .pronunciation-mora:last-child[data-position="0"][data-pitch="high"][data-pitch-next="low"]) .headword-term {
    color: var(--atamadaka-color) !important;
    --headword-current-kanji-border-color: var(--atamadaka-color) !important;
}
.pronunciation:has(.pronunciation-mora:last-child[data-position="0"][data-pitch="high"][data-pitch-next="low"]) {
    --pronunciation-annotation-color: var(--atamadaka-color) !important;
}

/* Increase border top width to make it look nicer */
.pronunciation-mora[data-pitch=high]>.pronunciation-mora-line {
    border-top-width: 0.15em;
}

